import {
  type NinePointAnchor,
  type Point,
  getZodPrefixedIdWithDefault,
  ninePointAnchor,
  point,
} from "src/common"
import {
  type ManufacturingDrcProperties,
  manufacturing_drc_properties,
} from "src/pcb/properties/manufacturing_drc_properties"
import { type Length, length } from "src/units"
import { expectTypesMatch } from "src/utils/expect-types-match"
import { z } from "zod"

export const pcb_board = z
  .object({
    type: z.literal("pcb_board"),
    pcb_board_id: getZodPrefixedIdWithDefault("pcb_board"),
    pcb_panel_id: z.string().optional(),
    carrier_pcb_board_id: z.string().optional(),
    is_subcircuit: z.boolean().optional(),
    subcircuit_id: z.string().optional(),
    is_mounted_to_carrier_board: z.boolean().optional(),
    is_via_in_pad_allowed: z.boolean().optional(),
    default_via_tented_on_top: z.boolean().optional(),
    default_via_tented_on_bottom: z.boolean().optional(),
    default_via_plugged: z.boolean().optional(),
    width: length.optional(),
    height: length.optional(),
    center: point,
    display_offset_x: z
      .string()
      .optional()
      .describe(
        "How to display the x offset for this board, usually corresponding with how the user specified it",
      ),
    display_offset_y: z
      .string()
      .optional()
      .describe(
        "How to display the y offset for this board, usually corresponding with how the user specified it",
      ),
    thickness: length.optional().default(1.4),
    num_layers: z.number().optional().default(4),
    allow_blind_and_buried_vias: z
      .boolean()
      .optional()
      .describe(
        "Whether autorouters may generate blind and buried vias. False restricts newly generated vias to the full board stack.",
      ),
    outline: z.array(point).optional(),
    shape: z.enum(["rect", "polygon"]).optional(),
    material: z.enum(["fr4", "fr1", "flex"]).default("fr4"),
    solder_mask_color: z.string().optional(),
    silkscreen_color: z.string().optional(),
    anchor_position: point.optional(),
    anchor_alignment: ninePointAnchor.optional(),
    position_mode: z.enum(["relative_to_panel_anchor", "none"]).optional(),
  })
  .merge(manufacturing_drc_properties)
  .describe("Defines the board outline of the PCB")

/**
 * Defines the board outline of the PCB
 */
export interface PcbBoard extends ManufacturingDrcProperties {
  type: "pcb_board"
  pcb_board_id: string
  pcb_panel_id?: string
  carrier_pcb_board_id?: string
  is_subcircuit?: boolean
  subcircuit_id?: string
  is_mounted_to_carrier_board?: boolean
  is_via_in_pad_allowed?: boolean
  default_via_tented_on_top?: boolean
  default_via_tented_on_bottom?: boolean
  default_via_plugged?: boolean
  width?: Length
  height?: Length
  display_offset_x?: string
  display_offset_y?: string
  thickness: Length
  num_layers: number
  /** Whether autorouters may generate blind and buried vias. */
  allow_blind_and_buried_vias?: boolean
  center: Point
  outline?: Point[]
  shape?: "rect" | "polygon"
  material: "fr4" | "fr1" | "flex"
  solder_mask_color?: string
  silkscreen_color?: string
  anchor_position?: Point
  anchor_alignment?: NinePointAnchor
  position_mode?: "relative_to_panel_anchor" | "none"
}

export type PcbBoardInput = z.input<typeof pcb_board>
type InferredPcbBoard = z.infer<typeof pcb_board>

/**
 * @deprecated use PcbBoard
 */
export type PCBBoard = PcbBoard

expectTypesMatch<PcbBoard, InferredPcbBoard>(true)
